use std::sync::{Arc, Mutex};
use std::thread;

fn recover_data(mutex: Arc<Mutex<i32>>) -> i32 {
    let _ = thread::spawn({
        let m = Arc::clone(&mutex);
        move || {
            let mut g = m.lock().unwrap();
            *g += 10;
            panic!();
        }
    }).join();
    let guard = match mutex.lock() {
        Ok(g) => g,
        Err(err) => ⟦slot1⟧,
    };
    ⟦slot2⟧
}

fn main() {
    let m = Arc::new(Mutex::new(0));
    recover_data(m);
}

tests:
#[test]
fn recovers_poisoned_value() {
    let m = Arc::new(Mutex::new(5));
    assert_eq!(recover_data(m), 15);
}
